switch (order.status) {
  case 'CART':
  case 'PAYMENT_FAILED':
    // 課金の記録がない（拒否された、または照合で記録なしと確かめた）
    order.status = 'CANCELLED';
    break;
  case 'PAID': { /* 今のまま */ }
  // PENDING_PAYMENT は課金されたか分からない。照合バッチが
  // PAID か PAYMENT_FAILED に確定させるまで待ってもらう
  default:
    throw new InvalidOrderStateError(order, 'cancelled');
}

function parseFeePercent(raw: string | undefined): number {
  if (raw === undefined || raw === '') return 10;
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 0 || n > 100) {
    throw new Error('CANCELLATION_FEE_PERCENT must be between 0 and 100: ' + raw);
  }
  return n;
}
